-- A purged table leaves its place without one (D83, D95; T79 ad/04): `places.table_id` is set to
-- null when the table goes, so the connector's row survives the purge of the venue it served and
-- the next read makes a new table if the place's till venue serves a venue again. Generated by
-- drizzle-kit, then the referential action written by hand: a plain `ON DELETE SET NULL` would
-- null the whole key, `tenant_id` included, which is NOT NULL; Postgres 17's column list nulls
-- only the column named.
ALTER TABLE "restro"."places" DROP CONSTRAINT "places_table_fk";
--> statement-breakpoint
ALTER TABLE "restro"."places" ADD CONSTRAINT "places_table_fk" FOREIGN KEY ("tenant_id","table_id") REFERENCES "restro"."tables"("tenant_id","id") ON DELETE SET NULL ("table_id") ON UPDATE no action;
